"""Write the PyInstaller --version-file resource for the WattPulse exe.

    python tools/version_info.py packaging\version_info.txt

The version is read from wattpulse/__init__.py so there is a single source of
truth (pyproject reads the same attribute).
"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))

from wattpulse import __version__  # noqa: E402

TEMPLATE = """\
# UTF-8 resource file generated by tools/version_info.py - do not edit by hand.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers=({parts}, 0),
    prodvers=({parts}, 0),
    mask=0x3f, flags=0x0, OS=0x40004, fileType=0x1, subtype=0x0, date=(0, 0)),
  kids=[
    StringFileInfo([
      StringTable('040904B0', [
        StringStruct('CompanyName', 'WattPulse Contributors'),
        StringStruct('FileDescription', 'WattPulse - live device power draw'),
        StringStruct('FileVersion', '{version}'),
        StringStruct('InternalName', 'wattpulse'),
        StringStruct('OriginalFilename', 'WattPulse.exe'),
        StringStruct('ProductName', 'WattPulse'),
        StringStruct('ProductVersion', '{version}')])]),
    VarFileInfo([VarStruct('Translation', [1033, 1200])])]
)
"""


def main(argv) -> int:
    out = Path(argv[1]) if len(argv) > 1 else ROOT / "packaging" / "version_info.txt"
    match = re.match(r"(\d+)\.(\d+)\.(\d+)", __version__)
    if not match:
        print(f"version_info: cannot parse {__version__!r}", file=sys.stderr)
        return 1
    parts = ", ".join(match.groups())
    out.write_text(TEMPLATE.format(parts=parts, version=__version__), encoding="utf-8")
    print(f"wrote {out} ({__version__})")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
